UPDATE SUserInterface.GridViewDefinitions SET RowStatus = 1, Guid = 'a6f9a1c2-6599-4346-a112-d9dc652cf1ab', Code = N'WORKFLOWSTATUS', GridDefinitionId = 109, DetailPageUri = N'DynamicEdit', SqlQuery = N'SELECT * 
FROM [SCore].[WorkflowStatus] root_hobt
WHERE 
	(root_hobt.RowStatus NOT IN (0,254)) AND
	( NOT EXISTS --Exclude system generated statuses.
			(
				SELECT 1 
				FROM [SCore].[WorkflowStatus]
				WHERE 
					ShowInEnquiries = 0 AND
					ShowInQuotes = 0 AND
					ShowInJobs = 0 AND
